<?php
namespace App\Modules\Scheduling\Jobs;
use App\Modules\Scheduling\Models\Appointment; use App\Modules\Scheduling\Notifications\AppointmentReminderNotification; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Queue\Queueable; use Illuminate\Support\Facades\{DB,Notification};
final class SendAppointmentReminders implements ShouldQueue {use Queueable; public function handle():void{foreach(config('scheduling.reminder_times',[]) as $minutes){$from=now()->addMinutes($minutes)->startOfMinute();$to=$from->copy()->addMinute();Appointment::query()->whereIn('status',['scheduled','confirmed'])->whereBetween('scheduled_start_at',[$from,$to])->each(function($a)use($minutes){DB::transaction(function()use($a,$minutes){$inserted=DB::table('scheduling_reminder_deliveries')->insertOrIgnore(['appointment_id'=>$a->id,'minutes_before'=>$minutes,'sent_at'=>now()]);if($inserted)Notification::route('mail',$a->guest_email)->notify(new AppointmentReminderNotification($a,$minutes));});});}}}
